rgbd = primitives.call(
    name='observe_robocasa_rgbd',
    camera_name='robot0_agentview_left',
    prompt='Report visible segmentation instances for the cabinetry, drawer, and drawer handle.',
    query='left drawer'
)
if rgbd.ok:
    print(rgbd.output)
else:
    print('rgbd failed')

s = primitives.call(name='observe_robocasa_rgbd', camera_name='robot0_agentview_left', prompt='List segmentation instance IDs and world positions for the blue cabinet drawers and their gold handles.', query='left drawer')
if s.ok:
    print(s.output)
else:
    print('observe failed')

d = primitives.call(name='observe_robocasa_rgbd', camera_name='robot0_agentview_left', prompt='Return segmentation IDs and 3D world positions for the visible left drawer front and its gold handle.', query='left drawer handle')
if d.ok:
    print(d.output)
else:
    print('rgbd error')

handles = []
def collect_evidence(x):
    if isinstance(x, dict):
        for k, v in x.items():
            if ('evidence_handle' in str(k)) and isinstance(v, str):
                handles.append(v)
            elif ('evidence_handles' in str(k)) and isinstance(v, list):
                for q in v:
                    if isinstance(q, str):
                        handles.append(q)
            collect_evidence(v)
    elif isinstance(x, list):
        for v in x:
            collect_evidence(v)

for source in [gw.output if gw.ok else None, g2.output if g2.ok else None, g.output if g.ok else None, loc.output if loc.ok else None]:
    collect_evidence(source)

unique_handles = []
for h in handles:
    if h not in unique_handles:
        unique_handles.append(h)
print('handles', unique_handles)

if len(unique_handles) > 0:
    m = primitives.call(
        name='move_robocasa_ee_to',
        evidence_handles=[unique_handles[0]],
        gripper_command=-1.0,
        horizon=50,
        offset=[0.06, 0.0, 0.0],
        prompt='Move with open gripper to the grounded horizontal gold pull of the left drawer.',
        query='left drawer handle pregrasp',
        target_name='drawer_obj',
        target_position=None
    )
    print('move_ok', m.ok, m.output)
else:
    print('no evidence handles extracted')

obs = primitives.call(
    name='observe_robocasa_rgbd',
    camera_name='robot0_agentview_left',
    prompt='Return all visible segmentation instance IDs with labels and representative 3D world positions. Identify the left drawer front and its gold handle.',
    query='left drawer handle segmentation'
)
if obs.ok:
    print(obs.output)
else:
    print('rgbd_failed')
